package dev.arcane.client.gui;

import dev.arcane.ArcaneSpells;
import dev.arcane.spell.Spell;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.renderer.RenderPipelines;
import net.minecraft.resources.Identifier;

/**
 * How each spell looks in the wheel and HUD: a 16×16 GUI sprite, from
 * {@code textures/gui/sprites/spell/<spell>.png} (generated by {@code tools/generate_assets.py}), and an ARGB accent
 * colour.
 */
public final class SpellIcons {
    private static final Identifier[] SPRITES = new Identifier[Spell.values().length];

    static {
        for (Spell spell : Spell.values()) SPRITES[spell.ordinal()] = ArcaneSpells.id("spell/" + spell.getSerializedName());
    }

    private SpellIcons() {
    }

    public static Identifier sprite(Spell spell) {
        return SPRITES[spell.ordinal()];
    }

    /** Draws the spell's icon with its top-left corner at x, y. */
    public static void draw(GuiGraphics graphics, Spell spell, int x, int y) {
        graphics.blitSprite(RenderPipelines.GUI_TEXTURED, sprite(spell), x, y, 16, 16);
    }

    public static int color(Spell spell) {
        return switch (spell) {
            case ARCANE_BOLT -> 0xFFB46CFF;
            case CHAIN_LIGHTNING -> 0xFF7EE8FF;
            case BLINK -> 0xFFF3B5FF;
            case ARCANE_WARD -> 0xFFFFD86B;
            case FROST_NOVA -> 0xFFCFF6FF;
        };
    }
}
